import React, { useState, useEffect, useRef } from 'react';
import { useI18n } from '../contexts/I18nContext';

interface AnimatedTextProps {
  translationKey: string;
  options?: any;
  className?: string;
  animationType?: 'default' | 'slide' | 'fade' | 'flip' | 'button' | 'header' | 'content' | 'nav' | 'stagger' | 'input';
  tag?: keyof React.JSX.IntrinsicElements;
  children?: React.ReactNode;
  staggerIndex?: number;
}

export const AnimatedText: React.FC<AnimatedTextProps> = ({
  translationKey,
  options,
  className = '',
  animationType = 'default',
  tag: Tag = 'span',
  children,
  staggerIndex = 0
}) => {
  const { t, currentLanguage } = useI18n();
  const [isAnimating, setIsAnimating] = useState(false);
  const [displayText, setDisplayText] = useState('');
  const previousLanguage = useRef(currentLanguage);
  const animationTimeoutRef = useRef<NodeJS.Timeout | null>(null);

  // Ініціалізація тексту
  useEffect(() => {
    if (!displayText) {
      setDisplayText(t(translationKey, options));
    }
  }, [t, translationKey, options, displayText]);

  // Анімація при зміні мови
  useEffect(() => {
    if (previousLanguage.current !== currentLanguage && displayText) {
      setIsAnimating(true);

      // Очищаємо попередній таймаут
      if (animationTimeoutRef.current) {
        clearTimeout(animationTimeoutRef.current);
      }

      // Затримка для stagger ефекту
      const staggerDelay = animationType === 'stagger' ? staggerIndex * 50 : 0;

      // Оновлюємо текст після анімації виходу
      animationTimeoutRef.current = setTimeout(() => {
        setDisplayText(t(translationKey, options));

        // Завершуємо анімацію після анімації входу
        const inAnimationDuration = getInAnimationDuration(animationType);
        setTimeout(() => {
          setIsAnimating(false);
        }, inAnimationDuration);
      }, getOutAnimationDuration(animationType) + staggerDelay);

      previousLanguage.current = currentLanguage;
    }
  }, [currentLanguage, t, translationKey, options, displayText, animationType, staggerIndex]);

  // Очищення таймауту при демонтуванні
  useEffect(() => {
    return () => {
      if (animationTimeoutRef.current) {
        clearTimeout(animationTimeoutRef.current);
      }
    };
  }, []);

  const getOutAnimationDuration = (type: string): number => {
    switch (type) {
      case 'slide': return 250;
      case 'fade': return 200;
      case 'flip': return 300;
      case 'button': return 200;
      case 'header': return 250;
      case 'content': return 200;
      case 'nav': return 150;
      case 'stagger': return 150;
      case 'input': return 200;
      default: return 300;
    }
  };

  const getInAnimationDuration = (type: string): number => {
    switch (type) {
      case 'slide': return 350;
      case 'fade': return 300;
      case 'flip': return 400;
      case 'button': return 300;
      case 'header': return 350;
      case 'content': return 300;
      case 'nav': return 250;
      case 'stagger': return 250;
      case 'input': return 300;
      default: return 400;
    }
  };

  const getAnimationClasses = (): string => {
    if (!isAnimating) return '';

    const baseClass = `language-${animationType}`;
    return `${baseClass}-out`;
  };

  const getInAnimationClasses = (): string => {
    if (!isAnimating) return '';

    const baseClass = `language-${animationType}`;
    return `${baseClass}-in`;
  };

  return React.createElement(
    Tag,
    {
      className: `animated-text-container ${className} ${getAnimationClasses()}`,
      style: {
        animationDelay: animationType === 'stagger' ? `${staggerIndex * 50}ms` : undefined
      }
    },
    React.createElement(
      'span',
      {
        className: `animated-text-content ${isAnimating ? getInAnimationClasses() : ''}`,
        key: `${currentLanguage}-${displayText}`
      },
      children || displayText
    )
  );
};

// Хук для анімації зміни мови
export const useLanguageAnimation = () => {
  const { currentLanguage } = useI18n();
  const [isChangingLanguage, setIsChangingLanguage] = useState(false);
  const previousLanguage = useRef(currentLanguage);

  useEffect(() => {
    if (previousLanguage.current !== currentLanguage) {
      setIsChangingLanguage(true);

      // Завершуємо анімацію через деякий час
      const timer = setTimeout(() => {
        setIsChangingLanguage(false);
      }, 800);

      previousLanguage.current = currentLanguage;

      return () => clearTimeout(timer);
    }
  }, [currentLanguage]);

  return { isChangingLanguage };
};

// Компонент-обгортка для анімації всього контенту
export const LanguageAnimationWrapper: React.FC<{
  children: React.ReactNode;
  className?: string;
}> = ({ children, className = '' }) => {
  const { isChangingLanguage } = useLanguageAnimation();

  return (
    <div 
      className={`${className} ${isChangingLanguage ? 'language-content-out' : 'language-content-in'}`}
      key={`wrapper-${isChangingLanguage}`}
    >
      {children}
    </div>
  );
};

export default AnimatedText;
